        _e("kv_websocket", "WebSocket & Real-time", "networking", "// Client\nconst ws = new WebSocket('wss://api.example.com/ws');\nws.onopen = () => ws.send(JSON.stringify({ type: 'join', room: 'chat' }));\nws.onmessage = (event) => {\n  const data = JSON.parse(event.data);\n  handleMessage(data);\n};\nws.onclose = () => reconnect();\nws.onerror = (err) => console.error(err);\n\n// Server (FastAPI)\nfrom fastapi import WebSocket\n@app.websocket('/ws/{client_id}')\nasync def websocket_endpoint(ws: WebSocket, client_id: str):\n    await ws.accept()\n    connections[client_id] = ws\n    try:\n        while True:\n            data = await ws.receive_json()\n            # Broadcast to all\n            for conn in connections.values():\n                await conn.send_json(data)\n    except WebSocketDisconnect:\n        del connections[client_id]\n\n// Server-Sent Events (SSE) — one-way server→client\n@app.get('/events')\nasync def events():\n    async def generate():\n        while True:\n            data = await get_update()\n            yield f'data: {json.dumps(data)}\\n\\n'\n    return StreamingResponse(generate(), media_type='text/event-stream')", ["websocket","real-time","sse","streaming","socket"]),
        _e("kv_graphql", "GraphQL", "graphql", "# Schema\ntype User {\n  id: ID!\n  name: String!\n  email: String!\n  posts: [Post!]!\n}\ntype Post {\n  id: ID!\n  title: String!\n  content: String!\n  author: User!\n}\ntype Query {\n  users: [User!]!\n  user(id: ID!): User\n  posts(limit: Int): [Post!]!\n}\ntype Mutation {\n  createUser(name: String!, email: String!): User!\n  createPost(title: String!, content: String!, authorId: ID!): Post!\n}\n\n# Query\nquery {\n  user(id: \"1\") {\n    name\n    posts {\n      title\n    }\n  }\n}\n\n# Mutation\nmutation {\n  createUser(name: \"Alice\", email: \"alice@test.com\") {\n    id\n    name\n  }\n}\n\n# Benefits: no over-fetching, single endpoint, typed schema, introspection\n# Drawbacks: complexity, N+1 queries (use DataLoader), caching harder", ["graphql","api","query","mutation","schema"]),

