        # ═══ DESIGN PATTERNS ═══
        _e("kv_patterns_solid", "SOLID Principles", "patterns", "S — Single Responsibility: One class = one reason to change\n  BAD: UserService handles auth + emails + database\n  GOOD: AuthService, EmailService, UserRepository\n\nO — Open/Closed: Open for extension, closed for modification\n  Use interfaces/abstract classes, strategy pattern\n  Add new behavior by adding new classes, not editing existing\n\nL — Liskov Substitution: Subtypes must be substitutable for base types\n  If Dog extends Animal, anywhere you use Animal, Dog should work\n  BAD: Square extends Rectangle but breaks setWidth/setHeight\n\nI — Interface Segregation: Many specific interfaces > one general\n  BAD: interface Worker { code(); test(); deploy(); manage(); }\n  GOOD: interface Coder { code(); } interface Tester { test(); }\n\nD — Dependency Inversion: Depend on abstractions, not concretions\n  BAD: class OrderService { private MySQLDatabase db; }\n  GOOD: class OrderService { private Database db; }  // interface", ["patterns","solid","design","principles","oop"]),
        _e("kv_patterns_gof", "GoF Design Patterns", "patterns", "Creational:\n  Singleton: One instance globally (db connection, config)\n  Factory: Create objects without specifying exact class\n  Builder: Step-by-step construction of complex objects\n  Prototype: Clone existing objects\n\nStructural:\n  Adapter: Convert interface to another (wrapper)\n  Decorator: Add behavior dynamically (middleware)\n  Facade: Simplified interface to complex subsystem\n  Proxy: Placeholder for another object (caching, lazy loading)\n  Composite: Tree structure (UI components)\n\nBehavioral:\n  Observer: Pub/sub, event listeners\n  Strategy: Swap algorithms at runtime\n  Command: Encapsulate action as object (undo/redo)\n  Iterator: Sequential access without exposing structure\n  State: Object behavior changes with internal state\n  Template Method: Define skeleton, let subclasses fill steps\n  Chain of Responsibility: Pass request through handler chain (middleware)\n\nMost used in web dev: Observer, Strategy, Factory, Decorator, Facade, Singleton", ["patterns","design-patterns","gof","creational","structural","behavioral"]),

        # ═══ LINUX/SHELL ═══
        _e("kv_linux", "Linux Essential Commands", "linux", "# File operations\nls -la          # List all with details\nfind . -name '*.py' -mtime -7  # Files modified in last 7 days\ngrep -rn 'pattern' .  # Recursive search with line numbers\nwc -l file.txt  # Count lines\ndu -sh */       # Directory sizes\ndf -h           # Disk usage\n\n# Process management\nps aux | grep python\ntop / htop      # Resource monitor\nkill -9 PID     # Force kill\nnohup cmd &     # Run in background\njobs / fg / bg  # Job control\n\n# Text processing\ncat file | sort | uniq -c | sort -rn  # Word frequency\nawk '{print $1, $3}' file  # Print columns 1 and 3\nsed 's/old/new/g' file     # Replace\ncut -d',' -f1,3 data.csv  # CSV columns\n\n# Networking\ncurl -s URL | jq .  # HTTP request + JSON parse\nwget URL            # Download\nss -tlnp            # Open ports\nping / traceroute   # Network diagnostics\n\n# Permissions\nchmod 755 script.sh  # rwxr-xr-x\nchown user:group file\nsudo command         # Run as root\n\n# Pipes & redirection\ncmd > file    # stdout to file\ncmd 2>&1      # stderr to stdout\ncmd1 | cmd2   # pipe", ["linux","shell","commands","bash","grep","awk","sed"]),

        # ═══ MONITORING ═══
        _e("kv_monitoring", "Application Monitoring", "devops", "# Key metrics (RED method)\nRate: Requests per second\nErrors: Error rate / percentage\nDuration: Latency (p50, p95, p99)\n\n# Prometheus metrics\nfrom prometheus_client import Counter, Histogram, Gauge\n\nREQUEST_COUNT = Counter('http_requests_total', 'Total requests', ['method', 'endpoint', 'status'])\nREQUEST_LATENCY = Histogram('http_request_duration_seconds', 'Request latency')\nACTIVE_USERS = Gauge('active_users', 'Currently active users')\n\n@app.middleware('http')\nasync def metrics_middleware(request, call_next):\n    start = time.time()\n    response = await call_next(request)\n    REQUEST_COUNT.labels(request.method, request.url.path, response.status_code).inc()\n    REQUEST_LATENCY.observe(time.time() - start)\n    return response\n\n# Logging best practices\nimport structlog\nlogger = structlog.get_logger()\nlogger.info('user_login', user_id='123', ip='1.2.3.4', duration_ms=45)\n\n# Stack: Prometheus + Grafana (metrics), ELK/Loki (logs), Jaeger (traces)\n# Alerts: PagerDuty, OpsGenie, Slack webhooks", ["monitoring","prometheus","grafana","logging","metrics","observability"]),
